# (first ASR segment, last ASR segment, Arabic, English, Chinese) -- times come from asr.json (silence-cut Whisper segments)
S = "ﷺ"
CAPS = [
 (0, 0, "حدّثتني أمٌّ عن يومٍ لن تنساه.", "A mother told me about a day she will never forget.", "一位母亲向我讲述了她永远不会忘记的一天。"),
 (1, 1, "كانت في زيارةٍ عند بعض الناس، وحين همّت بالقيام والانصراف مرّ بقلبها خاطرٌ سريع:", "She was visiting some people, and as she got up to leave, a quick thought crossed her heart:", "她当时在别人家做客,起身告辞时,心里闪过一个念头:"),
 (2, 2, "أخشى أن يصاب طفلي بالعين.", "“I fear my child may be struck by the evil eye.”", "“我担心我的孩子会中邪眼。”"),
 (3, 3, "خرجت وركبت السيارة، ولم تمضِ إلا دقائق حتى تقيّأ الصغير مرتين متتاليتين.", "She left and got into the car, and within minutes the little one vomited twice in a row.", "她出门上了车,才过了几分钟,孩子就连续吐了两次。"),
 (4, 5, "ومنذ ذلك اليوم.. تغيّر كل شيء.", "And from that day on... everything changed.", "从那天起……一切都变了。"),
 (6, 6, "بكاءٌ لا يهدأ، ولا نومَ في نهارٍ ولا في ليل،", "Crying that would not settle, no sleep by day or by night,", "哭闹不止,白天夜里都不睡,"),
 (7, 7, "خمسة أشهرٍ أو ستة،", "for five or six months,", "持续了五六个月,"),
 (8, 8, "وكلّ ما جرّبوه لم يُجْدِ شيئًا.", "and nothing they tried made any difference.", "他们试过的办法都没有用。"),
 (9, 9, "ثم بدأنا معه بالرقية الشرعية، وأوصينا أمَّه بالإكثار من الاستغفار، وأن تقرأ عليه صباحًا ومساءً سورًا وأدعية،", "Then we began sharʿī ruqyah with him, and advised his mother to make much istighfar and to recite over him morning and evening,", "后来我们为他开始了合乎教法的诵经祛病,并嘱咐他的母亲多求饶恕,早晚为他诵读,"),
 (10, 10, "والشفاء بيد الله وحده.", "and healing is in Allah’s hand alone.", "而治愈只掌握在真主手中。"),
 (11, 11, "وربما مررتِ أنتِ أيضًا بشيءٍ مثله؟", "Perhaps you, too, have been through something like it?", "也许你也经历过类似的事?"),
 (12, 12, "في هذه الحلقة نقف مع ما جاء في الكتاب والسنة عن العين التي تصيب الصغار، وكيف نعالجها ونقي أطفالنا منها بالطريقة الشرعية،", "In this episode we look at what the Qur’an and Sunnah say about the evil eye that strikes little ones, and how to treat it and protect our children in the lawful way,", "本期我们来看《古兰经》和圣训中关于伤害幼儿的邪眼的教导,以及如何以合乎教法的方式治疗并保护孩子,"),
 (13, 13, "وفي آخرها برنامجٌ يوميٌّ متكامل يمكنك أن تبدأ به من الليلة.", "and at the end, a complete daily plan you can start tonight.", "最后还有一套完整的每日方案,你今晚就可以开始。"),
 (14, 14, "العينُ.. حقيقةٌ أم وهم؟", "The evil eye... reality or illusion?", "邪眼……是真实还是幻觉?"),
 (15, 15, f"قال رسول الله {S}: «العين حق».", "The Messenger of Allah (peace be upon him) said: “The evil eye is real.”", f"真主的使者(愿主福安之)说:“邪眼是真实的。”"),
 (16, 16, "وفي رواية أخرى: «العين حق، ولو كان شيءٌ سابق القدر لسبقته العين».", "In another report: “The evil eye is real, and if anything could outrun destiny, the eye would.”", "另一传述:“邪眼是真实的;若有什么能超越前定,那便是邪眼。”"),
 (17, 18, "وذكر كثير من المفسرين أن قول الله تعالى: ﴿وَإِن يَكَادُ الَّذِينَ كَفَرُوا لَيُزْلِقُونَكَ بِأَبْصَارِهِمْ﴾ نزل في شأن العين.", "Many commentators mention that the words of Allah, “And those who disbelieve would almost make you slip with their eyes,” were revealed about the evil eye.", "许多注释家提到,真主的话“不信道者几乎要用他们的眼光使你跌倒”,就是针对邪眼而降示的。"),
 (19, 20, "لكن تذكّر دائمًا: العين لا تؤثّر إلا بإذن الله.", "But always remember: the eye only affects by Allah’s permission.", "但请永远记住:邪眼只有经真主允许才会起作用。"),
 (21, 22, "فليس لنظرة أحدٍ قوةٌ مستقلة، ولسنا بلا حماية؛ فالله هو الحافظ.", "No one’s glance has independent power, and we are not unprotected, for Allah is the Protector.", "任何人的目光都没有独立的力量,我们也并非没有保护,因为真主是保护者。"),
 (23, 23, "ولماذا يتأثر الأطفال أسرع من غيرهم؟", "And why are children affected faster than others?", "为什么孩子比别人更容易受影响?"),
 (24, 25, f"جاءت أسماء بنت عُميس إلى النبي {S} فقالت:", "Asmāʾ bint ʿUmays came to the Prophet (peace be upon him) and said:", "艾斯玛·宾特·欧迈斯来到先知(愿主福安之)面前,说:"),
 (26, 28, "يا رسول الله، إن ولد جعفر تسرع إليهم العين، أفأسترقي لهم؟", "“O Messenger of Allah, the eye is quick to reach Jaʿfar’s children. Shall I seek ruqyah for them?”", "“真主的使者啊,邪眼很容易伤到贾法尔的孩子,我可以为他们诵经祛病吗?”"),
 (29, 30, "فقال: «نعم، فإنه لو كان شيءٌ سابق القدر لسبقته العين».", "He said: “Yes, for if anything could outrun destiny, the eye would.”", "他说:“可以,因为若有什么能超越前定,那便是邪眼。”"),
 (31, 33, f"ورأى {S} في بيت أم سلمة جاريةً في وجهها سَفْعة، أي تغيّرٌ في لونها،", "And in the house of Umm Salama he saw a girl with a safʿa on her face, a change in her colour,", "他(愿主福安之)在乌姆·塞莱麦家中见到一个女孩,脸上有“萨夫阿”,也就是肤色发生了变化,"),
 (34, 36, "فقال: «استرقوا لها، فإن بها النظرة».", "and said: “Seek ruqyah for her, for she has been struck by the eye.”", "于是说:“为她诵经祛病吧,她被邪眼伤到了。”"),
 (37, 37, "الطفل جميل، تتعلق به الأنظار، ويُثنى عليه، وتتناقل الهواتف صورته،", "A child is lovely; eyes cling to him, he is praised, and phones pass his picture around,", "孩子惹人喜爱,目光都被他吸引,人们称赞他,手机里到处传着他的照片,"),
 (38, 38, "وهو لا يملك أن يذكر الله على نفسه أو يحصّنها.", "while he cannot mention Allah over himself or protect himself.", "而他自己无法诵念真主之名,也无法保护自己。"),
 (39, 39, "فتحصينه أمانةٌ في عنق الوالدين.", "So protecting him is a trust upon the parents’ necks.", "因此保护他是父母肩上的一项责任。"),
 (40, 40, "علاماتٌ يذكرها الرقاة", "Signs that those who practise ruqyah mention", "诵经者常提到的迹象"),
 (41, 42, "يذكر أهل الخبرة بالرقية علاماتٍ تظهر في الغالب فجأة، بعد زيارةٍ أو مديحٍ أو نظرة:", "Experienced practitioners mention signs that usually appear suddenly, after a visit, a compliment or a glance:", "有经验的诵经者提到一些通常突然出现的迹象,多在做客、被夸赞或被注视之后:"),
 (43, 43, "بكاءٌ طويل بلا سببٍ ظاهر،", "long crying with no apparent cause,", "无明显原因的长时间啼哭,"),
 (44, 44, "وسهرٌ في الليل والنهار،", "sleeplessness night and day,", "日夜不眠,"),
 (45, 45, "وإعراضٌ عن الرضاعة،", "refusing to feed,", "拒绝吃奶,"),
 (46, 46, "وقلقٌ حتى وهو في حضن أمه،", "restlessness even in his mother’s arms,", "即使在母亲怀里也烦躁不安,"),
 (47, 47, "وفزعٌ مفاجئ من النوم.", "and sudden fright from sleep.", "以及从睡梦中突然惊醒。"),
 (48, 48, "غير أن هذه العلامات ليست قطعية،", "Yet these signs are not conclusive,", "不过这些迹象并不是定论,"),
 (49, 49, "فليس كل بكاءٍ عينًا،", "for not every cry is the eye,", "因为并非每次哭闹都是邪眼,"),
 (50, 50, "فلا ننسب كل شيء إلى العين، ولا نتهم أحدًا بغير بيّنة.", "so we do not blame everything on the eye, nor accuse anyone without proof.", "所以我们不要把一切都归咎于邪眼,也不要在没有证据时指责任何人。"),
 (51, 52, "والجميل في الرقية الشرعية أنها إن كانت عينًا فهي بإذن الله شفاء، وإن لم تكن فهي ذكرٌ ودعاءٌ وبركة، لا ضرر فيها.", "The beauty of sharʿī ruqyah is that if it is the eye, then by Allah’s leave it is a cure, and if not, it is remembrance, prayer and blessing, with no harm in it.", "合乎教法的诵经祛病的美好在于:若是邪眼,则凭真主的许可就是治疗;若不是,那也是赞念、祈祷与吉祥,毫无害处。"),
 (53, 54, "والآن، العلاج خطوةً خطوة.", "And now, the treatment, step by step.", "现在,一步一步来看治疗方法。"),
 (55, 56, "الخطوة الأولى: اليقين والتوكل.", "Step one: certainty and reliance on Allah.", "第一步:笃信与托靠真主。"),
 (57, 57, "قال تعالى: ﴿وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِّلْمُؤْمِنِينَ﴾", "Allah says: “And We send down of the Qur’an that which is healing and mercy for the believers.”", "真主说:“我降示《古兰经》,对于信士们,是治疗,是恩惠。”"),
 (58, 58, "اقرأ وأنتِ موقنةٌ أن الشافي هو الله وحده، لا أنتِ ولا كلماتك.", "Recite while certain that the Healer is Allah alone, not you and not your words.", "诵读时要笃信:治愈者唯有真主,不是你,也不是你的言语。"),
 (60, 61, "الخطوة الثانية: القراءة على الطفل.", "Step two: reciting over the child.", "第二步:为孩子诵读。"),
 (62, 62, f"أخبرت عائشة رضي الله عنها أن النبي {S} كان إذا اشتكى قرأ على نفسه بالمعوذات ونفث.", "ʿĀʾisha (may Allah be pleased with her) reported that when the Prophet (peace be upon him) fell ill, he would recite the Muʿawwidhāt over himself and blow lightly.", "阿伊莎(愿主喜悦她)转述:先知(愿主福安之)患病时,会为自己诵读护佑三章并轻轻吹气。"),
 (63, 63, "فاجلسي قرب طفلك متوضئة،", "Sit near your child in a state of wudūʾ,", "在孩子身边坐下,保持洁净,"),
 (64, 64, "وضعي يدك اليمنى برفق على رأسه أو صدره،", "place your right hand gently on his head or chest,", "把右手轻轻放在他的头上或胸口,"),
 (65, 65, "واقرئي وانفثي عليه نفثًا خفيفًا بعد كل سورة.", "and recite, blowing lightly over him after each sura.", "边诵读边轻轻地向他吹气,每读完一章吹一次。"),
 (66, 66, "وفي كل صباحٍ ومساء:", "Every morning and evening:", "每天早晚:"),
 (67, 69, "الفاتحة سبع مرات، وآية الكرسي، وخواتيم سورة البقرة «آمَنَ الرَّسُولُ»،", "Al-Fātiḥa seven times, Āyat al-Kursī, and the last verses of Sūrat al-Baqara, “The Messenger believes”,", "《开端章》七遍,《宝座节》,以及《黄牛章》的末尾几节“使者确信……”,"),
 (70, 72, "والإخلاص والفلق والناس، ثلاثًا ثلاثًا.", "and al-Ikhlāṣ, al-Falaq and an-Nās, three times each.", "还有《忠诚章》《曙光章》《世人章》,各三遍。"),
 (74, 77, f"أما الفاتحة فقد رقى بها صحابيٌّ مريضًا فشُفي، فقال له النبي {S}: «وما يدريك أنها رقية؟»", "As for al-Fātiḥa, a Companion recited it over a sick man and he recovered, and the Prophet (peace be upon him) said to him: “How did you know it is a ruqyah?”", "至于《开端章》,一位圣门弟子用它为病人诵读,病人痊愈了,先知(愿主福安之)对他说:“你怎么知道它是诵经祛病的经文?”"),
 (78, 79, "وعدد السبع من تجارب الرقاة، والمعوَّل عليه حضور القلب.", "The number seven comes from the experience of practitioners; what matters is a present heart.", "七遍这个数字来自诵经者的经验,真正要紧的是专注的心。"),
 (80, 82, "وآية الكرسي: «من قرأها لم يزل عليه من الله حافظ، ولا يقربه شيطانٌ حتى يصبح».", "Āyat al-Kursī: “Whoever recites it will have a guardian from Allah over him, and no devil will come near him until morning.”", "《宝座节》:“谁诵读它,就会有真主派来的守护者一直守着他,直到天亮,恶魔都不会靠近。”"),
 (83, 84, "وخواتيم البقرة: «من قرأهما في ليلةٍ كفتاه».", "The end of al-Baqara: “Whoever recites the two in a night, they will suffice him.”", "《黄牛章》的末尾:“谁在夜里诵读这两节,它们就足够他用了。”"),
 (85, 87, f"والمعوذات قال فيها {S}: «تقرؤها حين تمسي وحين تصبح ثلاثًا، تكفيك من كل شيء».", "Of the Muʿawwidhāt he (peace be upon him) said: “Recite them when you reach evening and when you reach morning, three times; they will suffice you against everything.”", "关于护佑三章,他(愿主福安之)说:“傍晚和早晨各诵三遍,它们足以护佑你远离一切。”"),
 (89, 89, f"الخطوة الثالثة: أدعية النبي {S}.", "Step three: the supplications of the Prophet (peace be upon him).", "第三步:先知(愿主福安之)的祈祷词。"),
 (90, 91, "كان يعوّذ الحسن والحسين بقوله: «أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ».", "He used to seek refuge for al-Ḥasan and al-Ḥusayn with the words: “I seek refuge for you in the perfect words of Allah from every devil and every harmful creature, and from every evil eye.”", "他常这样为哈桑和侯赛因祈求庇护:“我借真主完美的言辞,为你们二人求护佑,远离一切恶魔、一切毒虫和一切邪眼。”"),
 (92, 92, "فقولي لطفلك: أُعِيذُكَ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ.", "So say to your child: “I seek refuge for you in the perfect words of Allah from every devil and every harmful creature, and from every evil eye.”", "你就对孩子说:“我借真主完美的言辞,为你求护佑,远离一切恶魔、一切毒虫和一切邪眼。”"),
 (93, 94, f"ورقى جبريل عليه السلام النبيَّ {S} فقال: «بِاسْمِ اللَّهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ،", "Jibrīl (peace be upon him) performed ruqyah for the Prophet (peace be upon him), saying: “In the name of Allah I perform ruqyah for you, from everything that harms you, from the evil of every soul or envious eye,", "吉卜利勒(愿主福安之)曾为先知(愿主福安之)诵经祛病,说:“奉真主之名我为你诵经,远离一切伤害你的事物,远离每个灵魂和每只嫉妒之眼的恶害,"),
 (95, 96, "اللَّهُ يَشْفِيكَ، بِاسْمِ اللَّهِ أَرْقِيكَ».", "may Allah heal you; in the name of Allah I perform ruqyah for you.”", "愿真主治愈你;奉真主之名我为你诵经。”"),
 (97, 97, "وادعي:", "And pray:", "并且祈祷:"),
 (98, 98, "«اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ الْبَأْسَ، اشْفِهِ وَأَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا».", "“O Allah, Lord of mankind, remove the harm; heal him, for You are the Healer; there is no healing but Your healing, a healing that leaves no illness behind.”", "“真主啊,世人的养育者,请消除病痛,请治愈他,因为您是治愈者;除您的治愈之外,没有任何治愈,请赐予不留下任何病痛的治愈。”"),
 (99, 99, "وقولي سبع مرات: «أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ».", "And say seven times: “I ask Allah the Almighty, Lord of the Mighty Throne, to heal you.”", "并说七遍:“我祈求伟大的真主,伟大宝座的养育者,治愈你。”"),
 (100, 101, "الخطوة الرابعة: ماء الرقية.", "Step four: the water of ruqyah.", "第四步:诵经之水。"),
 (102, 103, "اقرئي هذه السور والأدعية على إناءِ ماء، وانفثي فيه.", "Recite these suras and supplications over a vessel of water, and blow lightly into it.", "对着一容器水诵读这些章节和祈祷词,并轻轻向其中吹气。"),
 (104, 104, "فإن كان الطفل كبيرًا شرب منه،", "If the child is older, he drinks from it,", "如果孩子大一些,就让他喝一些,"),
 (105, 105, "وإن كان رضيعًا فامسحي بالماء وجهه ويديه وقدميه،", "and if he is an infant, wipe his face, hands and feet with the water,", "如果是婴儿,就用这水擦拭他的脸、手和脚,"),
 (106, 106, "وقد أجاز ذلك كثيرٌ من أهل العلم.", "and many scholars have permitted this.", "许多学者都认为这样做是被允许的。"),
 (107, 108, "الخطوة الخامسة: استغفار الوالدين.", "Step five: the parents’ istighfar.", "第五步:父母的求饶恕。"),
 (109, 111, "استغفري ربكِ، فقد يكون هناك سببٌ لا نعلمه، فيكون الاستغفار سببًا في الشفاء.", "Seek your Lord’s forgiveness, for there may be a cause we do not know, and istighfar may become a cause of healing.", "请向你的养主求饶恕,也许有我们不知道的原因,而求饶恕可以成为治愈的缘由。"),
 (112, 116, "قال تعالى على لسان نوح عليه السلام: ﴿فَقُلْتُ اسْتَغْفِرُوا رَبَّكُمْ إِنَّهُ كَانَ غَفَّارًا * يُرْسِلِ السَّمَاءَ عَلَيْكُم مِّدْرَارًا * وَيُمْدِدْكُم بِأَمْوَالٍ وَبَنِينَ﴾", "Allah says on the tongue of Nūḥ (peace be upon him): “I said: seek forgiveness of your Lord, He is ever Forgiving; He will send rain upon you in abundance, and support you with wealth and children.”", "真主借努哈(愿主福安之)之口说:“我说:你们当向你们的养主求饶恕,他确是至赦的,他将降大雨给你们,并以财产和子嗣援助你们。”"),
 (117, 117, "تأمّلي كيف ربط الله الاستغفار بالبركة في الأبناء.", "Reflect how Allah linked istighfar with blessing in children.", "想一想,真主是如何把求饶恕与子嗣的吉庆联系在一起的。"),
 (118, 118, "فأكثري منه يا أماه، وأنتِ في عمل البيت وفي الطريق وبجوار مهد صغيرك، وادعي له بقلبٍ منكسر.", "So make much of it, dear mother, as you do housework, on the road, and beside your little one’s cradle, and pray for him with a broken heart.", "亲爱的母亲,请多多求饶恕:做家务时、路上、在孩子的摇篮旁,都要如此,并带着谦卑的心为他祈祷。"),
 (119, 120, "الخطوة السادسة: اغتسال العائن", "Step six: the washing of the one who cast the eye", "第六步:施以邪眼者的洗涤"),
 (121, 122, f"أصيب سهل بن حنيف بالعين فصُرع، فقال النبي {S} للذي أصابه: «عَلَامَ يَقْتُلُ أَحَدُكُمْ أَخَاهُ؟ أَلَا بَرَّكْتَ؟»", "Sahl ibn Ḥunayf was struck by the eye and collapsed, and the Prophet (peace be upon him) said to the one who struck him: “Why does one of you kill his brother? Why did you not invoke blessing?”", "赛赫勒·本·侯奈夫被邪眼所伤而倒下,先知(愿主福安之)对伤他的人说:“你们中的某人为什么要伤害自己的兄弟?你为什么不祈求吉庆呢?”"),
 (123, 124, "وأمره أن يغتسل له، فقام سهلٌ معافى.", "And he ordered him to wash for him, and Sahl got up, healed.", "并命令他为赛赫勒洗涤,赛赫勒随即康复地站了起来。"),
 (125, 125, f"وقال {S}: «وإذا استُغسلتم فاغسلوا».", "And he (peace be upon him) said: “If you are asked to wash, then wash.”", "他(愿主福安之)说:“若被要求洗涤,你们就洗涤。”"),
 (126, 126, "لكن هذا عند اليقين لا بالظن والتخمين،", "But this is only where there is certainty, not suspicion or guesswork,", "但这只适用于确定的情况,而不是凭猜测和臆断,"),
 (127, 127, "ويُطلب بلطفٍ ومن غير خصام.", "and it is requested gently, without dispute.", "并且要温和地提出,不起争执。"),
 (128, 129, "الخطوة السابعة: الصبر والمداومة.", "Step seven: patience and persistence.", "第七步:耐心与坚持。"),
 (130, 131, "الرقية ليست عمل يومٍ واحد، داومي عليها أيامًا وأسابيع ولا تيأسي،", "Ruqyah is not the work of a single day; keep at it for days and weeks and do not despair,", "诵经祛病不是一天的事,请坚持数日、数周,不要灰心,"),
 (132, 132, "فالشفاء يأتي في الوقت الذي يريده الله.", "for healing comes at the time Allah wills.", "因为治愈会在真主所意欲的时刻到来。"),
 (133, 133, "واحذري الدجالين.", "And beware of charlatans.", "还要提防骗子。"),
 (134, 134, f"قال {S}: «لا بأس بالرُّقى ما لم يكن فيه شرك»، وقال: «من علّق تميمةً فقد أشرك».", "He (peace be upon him) said: “There is no harm in ruqyah as long as it contains no shirk,” and said: “Whoever hangs an amulet has committed shirk.”", "他(愿主福安之)说:“只要不含举伴,诵经祛病无妨。”又说:“谁佩戴护身符,谁就是举伴了。”"),
 (135, 136, "فإن كتب أحدٌ لطفلك طلسمًا، أو أعطاك ورقةً بكلامٍ غير مفهوم، أو سألك عن اسم أمّك، أو طلب ذبح حيوان، فاعلمي أن هذا ليس طريق الشرع.", "If someone writes a talisman for your child, hands you a paper of unintelligible words, asks for your mother’s name, or asks you to slaughter an animal, know that this is not the way of the sharīʿa.", "如果有人给你的孩子写符咒,递给你一张看不懂的纸,询问你母亲的名字,或要求宰杀牲畜,请知道这不是教法之道。"),
 (137, 138, "الرقية الشرعية قرآنٌ وأدعيةٌ نبوية، بلسانٍ واضحٍ تفهمينه، وأنتِ وأبوه أولى الناس بأن تقرؤوها عليه.", "Sharʿī ruqyah is Qur’an and prophetic supplications, in clear words you understand, and you and his father are the people most entitled to recite it over him.", "合乎教法的诵经祛病就是《古兰经》和先知的祈祷词,用你听得懂的清晰语言诵读,你和他的父亲最有资格为他诵读。"),
 (139, 140, f"وتذكّري قوله {S}: «تداووا عباد الله».", "And remember his saying (peace be upon him): “Seek treatment, servants of Allah.”", "并请记住他(愿主福安之)的话:“真主的仆人们,你们要就医。”"),
 (141, 141, "فالرقية لا تلغي الأخذ بالأسباب، بل تُسانِدها،", "Ruqyah does not cancel taking the means; it supports them,", "诵经祛病并不取代采取措施,而是与之相辅相成,"),
 (142, 142, "والوقاية خيرٌ من انتظار البلاء.", "and prevention is better than waiting for affliction.", "预防胜过等待灾祸降临。"),
 (143, 144, "إذا أعجبك شيءٌ من طفلٍ فقولي: ما شاء الله لا قوة إلا بالله، أو: بارك الله فيه.", "If something about a child impresses you, say: “What Allah wills, there is no power but with Allah,” or: “May Allah bless him.”", "如果你喜欢某个孩子的某一点,请说:“这是真主的意愿,除非借真主,没有力量。”或:“愿真主祝福他。”"),
 (145, 146, "قال تعالى: ﴿وَلَوْلَا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ﴾", "Allah says: “If only, when you entered your garden, you had said: What Allah wills; there is no power but with Allah.”", "真主说:“当你进入你的园圃时,你为什么不说:‘这是真主的意愿,除非借真主,没有力量’呢?”"),
 (147, 148, f"وقال {S}: «إذا رأى أحدكم من أخيه ما يعجبه فليدعُ له بالبركة».", "And he (peace be upon him) said: “If one of you sees something he admires in his brother, let him invoke blessing for him.”", "他(愿主福安之)说:“你们中若有人看到兄弟身上令他喜欢的东西,就让他为他祈求吉庆。”"),
 (149, 149, "وقلّلي من نشر صور طفلك ولحظاته الخاصة على مواقع التواصل، فليست كل نظرةٍ مصحوبةً بالدعاء.", "And share fewer of your child’s pictures and private moments on social media, for not every glance comes with a prayer.", "也请少在社交媒体上发布孩子的照片和私密时刻,因为并不是每一道目光都伴有祈祷。"),
 (150, 151, f"وحصّنيه صباحًا ومساءً بتعويذة النبي {S}، وقولي ثلاثًا:", "Protect him morning and evening with the Prophet’s protective words (peace be upon him), and say three times:", "每天早晚用先知(愿主福安之)的护佑词保护他,并说三遍:"),
 (152, 153, "«بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ».", "“In the name of Allah, with whose name nothing on earth or in heaven can cause harm, and He is the All-Hearing, the All-Knowing.”", "“奉真主之名,有他的名字在,天地间任何事物都不能为害;他是全听的,全知的。”"),
 (154, 155, f"وأحيي بيتك بالقرآن، فقد أخبر {S} أن الشيطان ينفر من البيت الذي تُقرأ فيه سورة البقرة.", "And fill your home with Qur’an, for he (peace be upon him) told us that the devil flees from a house in which Sūrat al-Baqara is recited.", "也请让你的家充满《古兰经》的诵读,因为他(愿主福安之)告诉我们,恶魔会逃离诵读《黄牛章》的房子。"),
 (156, 157, "وخلاصة القول: العين حق، لكن الله أكبر من كل نظرة،", "In short: the eye is real, but Allah is greater than every glance,", "总之:邪眼是真实的,但真主比任何目光都伟大,"),
 (158, 158, "والقرآن شفاء، لكن الشافي هو الله،", "the Qur’an is healing, but the Healer is Allah,", "《古兰经》是治疗,但治愈者是真主,"),
 (159, 159, "والوالدان هما أول من يرقي الطفل، وأولى الناس بذلك.", "and the parents are the first to recite ruqyah over the child and the people most entitled to do so.", "父母是第一个为孩子诵经祛病的人,也是最有资格的人。"),
 (160, 161, "إن كنتَ تعرف أمًّا تسهر الليالي بجوار مهد صغيرها فأرسل لها هذا المقطع، واكتب في التعليقات دعاءً لكل طفلٍ مريض.", "If you know a mother who stays up nights beside her little one’s cradle, send her this clip, and write in the comments a prayer for every sick child.", "如果你认识一位在孩子摇篮边彻夜难眠的母亲,请把这段视频发给她,并在评论中为每一个生病的孩子写下祈祷。"),
 (162, 162, "«اللَّهُمَّ اشْفِ أَطْفَالَنَا وَأَطْفَالَ الْمُسْلِمِينَ، وَأَلْبِسْهُمْ ثَوْبَ الْعَافِيَةِ».", "“O Allah, heal our children and the children of the Muslims, and clothe them in the garment of well-being.”", "“真主啊,求您治愈我们的孩子和穆斯林的孩子们,并让他们穿上安康的衣裳。”"),
 (163, 163, "آمين.", "Amen.", "阿敏。"),
]
